<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Imperium\Runtime\Senate\SymfonyAiProfileExaminationDispositionCognitionGateway;use PHPUnit\Framework\TestCase;use Symfony\AI\Agent\AgentInterface;use Symfony\AI\Platform\Result\TextResult;
final class SymfonyAiProfileExaminationDispositionCognitionGatewayTest extends TestCase{public function testAcceptsExactContract():void{$v=['disposition'=>'APPROVED','finding_references'=>['a','b','c'],'rationale'=>'Bounded.','reconciliation_treatment'=>'Preserved.','limitations'=>[],'uncertainties'=>[]];self::assertSame($v,$this->g(json_encode($v,JSON_THROW_ON_ERROR))->decide([],[],[]));}public function testRejectsExtraField():void{$this->expectExceptionMessage('S280_PROFILE_EXAMINATION_DISPOSITION_COGNITION_INVALID: FIELDS_INVALID');$this->g('{"disposition":"APPROVED","finding_references":[],"rationale":"x","reconciliation_treatment":"x","limitations":[],"uncertainties":[],"approval_authority":true}')->decide([],[],[]);}public function testRejectsInvalidJson():void{$this->expectExceptionMessage('S280_PROFILE_EXAMINATION_DISPOSITION_COGNITION_INVALID: JSON_INVALID');$this->g('APPROVED')->decide([],[],[]);}private function g(string$r):SymfonyAiProfileExaminationDispositionCognitionGateway{$a=$this->createStub(AgentInterface::class);$a->method('call')->willReturn(new TextResult($r));return new SymfonyAiProfileExaminationDispositionCognitionGateway($a);}}
